(function(){'use strict';
const $=id=>document.getElementById(id),core=window.CafeBoardCore,query=new URLSearchParams(location.search),demo=query.get('demo')==='1';
let snapshot=null,lastGood=0,offset=0,signature='',connected=false,layoutPending=false,staffPage=0,staffAt=0,staffGroups=[];
const columns=['cooking','ready'].map(name=>({name,pages:[],page:0,at:0})),seenReady=new Set(),highlightUntil=new Map();
if(location.hash)history.replaceState(null,'',location.pathname+location.search);
const text=(tag,value,cls)=>{const el=document.createElement(tag);if(cls)el.className=cls;el.textContent=value;return el;};
function boardText(){return window.CafeBoardText.resolve(snapshot?.boardText);}
function bindBoardText(values){for(const el of document.querySelectorAll('[data-board-text]')){const value=values[el.dataset.boardText];el.textContent=value;if(!['brandName','cookingTitle','readyTitle'].includes(el.dataset.boardText))el.hidden=value==='';}}
function card(order,part,index=0,total=1){
 const el=text('article','','card');el.dataset.order=order.id;el.dataset.part=index;const identity=text('div','','identity'),number=text('div','','number');number.append(text('span','№ '),document.createTextNode(window.STARTCafeNumber(order.id)));identity.append(number);

 if(total>1)identity.append(text('div',(index?'Продолжение':'Начало')+' · '+(index+1)+'/'+total,'continuation'));
 const items=text('div','','items');for(const item of part.items){const dish=text('div','','dish');dish.append(text('div',item.quantity+' × '+item.name,'dish-title'));const notes=[item.variant,...(item.modifiers||[]),item.comment].filter(Boolean);if(notes.length)dish.append(text('div','↳ '+notes.join(', '),'dish-notes'));items.append(dish);}const meta=text('div','','card-meta'),settings=boardText(),pickup=order.location==='Самовывоз';meta.append(text('div',order.status==='ready'?settings.readyMessage+' · '+(pickup?settings.pickupLabel:core.readyHint(order.location)):(pickup?settings.pickupLabel:core.receiving(order.location)),order.status==='ready'?'ready-label':'fulfillment'));items.append(meta);el.append(identity,items);
 if(part.comment){const comment=text('div','','comment');comment.append(text('span','Комментарий: ','comment-label'),document.createTextNode(part.comment));el.append(comment);}
 if(order.status==='cooking'){const timer=text('div',(order.waitingBasis==='work'?'В работе ':'С момента заказа ')+Math.max(0,Math.floor((Date.now()+offset-order.waitingSince)/60000))+' мин','timer');timer.dataset.since=order.waitingSince;timer.dataset.basis=order.waitingBasis||'created';meta.append(timer);}
 return el;
}
function empty(name){const settings=boardText(),el=text('div','','empty'),hint=name==='cooking'?settings.emptyCookingHint:settings.emptyReadyHint;el.append(text('h2',name==='cooking'?settings.emptyCookingTitle:settings.emptyReadyTitle));if(hint)el.append(text('p',hint));if(name==='ready'){const qr=document.createElement('img');qr.className='qr';qr.src='/cafe-board-menu-qr.svg';qr.alt='QR-код меню: spotsup.ru/cafe/';qr.width=170;qr.height=170;el.append(qr,text('p','Меню и заказ','qr-label'));}return el;}
function rebuild(focusReady=[]){layoutPending=false;if(!snapshot)return;
 for(const col of columns){const list=$(col.name),orders=snapshot.orders.filter(o=>o.status===col.name),anchor=col.pages[col.page]?.[0],oldPage=JSON.stringify(col.pages[col.page]),height=list.clientHeight,gap=parseFloat(getComputedStyle(list).gap)||12;$(col.name+'-count').textContent=orders.length;
  const measureBox=text('div','','measure '+col.name);measureBox.style.width=list.clientWidth+'px';document.body.append(measureBox);const entries=[];
  try{for(const order of orders){const measure=part=>{const node=card(order,part,1,99);measureBox.replaceChildren(node);return Math.ceil(node.getBoundingClientRect().height);};const parts=core.splitOrder(order,height,measure);parts.forEach((content,part)=>{const node=card(order,content,part,parts.length);measureBox.replaceChildren(node);entries.push({order,content,part,total:parts.length,height:Math.ceil(node.getBoundingClientRect().height)});});}}finally{measureBox.remove();}
  col.pages=core.boardPages(entries,height,gap);let page=anchor?col.pages.findIndex(p=>p.some(e=>e.order.id===anchor.order.id&&e.part===anchor.part)):-1;if(page<0)page=0;
  if(col.name==='ready'&&focusReady.length){const found=col.pages.findIndex(p=>p.some(e=>focusReady.includes(e.order.id)));if(found>=0)page=found;}
  col.page=page;if(oldPage!==JSON.stringify(col.pages[page]))col.at=Date.now();render(col);
 }timers();
}
function render(col){const list=$(col.name),page=col.pages[col.page]||[],existing=new Map([...list.querySelectorAll('.card')].map(n=>[n.dataset.order+':'+n.dataset.part,n])),copySignature=JSON.stringify(boardText());const nodes=page.map(e=>{const key=e.order.id+':'+e.part,sig=JSON.stringify([e,copySignature]);let n=existing.get(key);if(!n||n.dataset.signature!==sig){n=card(e.order,e.content,e.part,e.total);n.dataset.signature=sig;if(col.name==='ready'&&(highlightUntil.get(e.order.id)||0)>Date.now())n.classList.add('is-new');}return n;});if(!nodes.length)nodes.push(empty(col.name));list.replaceChildren(...nodes);$(col.name+'-page').textContent=col.pages.length>1?'Страница '+(col.page+1)+' из '+col.pages.length:'';col.seconds=Math.max(12,core.pageSeconds(page));timers();}
function timers(){if(!snapshot)return;const now=Date.now()+offset;for(const el of document.querySelectorAll('.timer')){const minutes=Math.max(0,Math.floor((now-Number(el.dataset.since))/60000));el.textContent=(el.dataset.basis==='work'?'В работе ':'С момента заказа ')+minutes+' мин';el.closest('.card').classList.toggle('overdue',snapshot.warningMinutes>0&&minutes>=snapshot.warningMinutes);}}
function layoutStaff(){const names=snapshot?.staffNames||[],box=$('staff-header'),label=$('staff-names');box.hidden=!names.length;staffGroups=[];if(!names.length)return;let group=[];for(const name of names){label.textContent=core.staffText([...group,name]);if(group.length&&label.scrollWidth>box.clientWidth){staffGroups.push(group);group=[name];}else group.push(name);}if(group.length)staffGroups.push(group);staffPage=Math.min(staffPage,staffGroups.length-1);label.textContent=core.staffText(staffGroups[staffPage]);}
function connection(ok){const changed=connected!==ok;connected=ok;document.body.classList.toggle('stale',!ok);$('notice').hidden=ok;if(!ok)$('notice').textContent=lastGood?'Нет связи. Показаны данные на '+new Date(lastGood).toLocaleTimeString('ru-RU',{timeZone:'Europe/Moscow',hour:'2-digit',minute:'2-digit'})+'.':'Подключаемся к табло. Заказы пока не загружены.';if(changed&&snapshot)requestAnimationFrame(()=>{rebuild();layoutStaff();});}
function accept(data){if(!Array.isArray(data.orders)||!Number.isFinite(data.serverTime))throw Error('Некорректный ответ сервера');const first=!snapshot,reconnecting=!connected;offset=data.serverTime-Date.now();lastGood=data.serverTime;
 const arrivals=first?[]:data.orders.filter(o=>o.status==='ready'&&!seenReady.has(o.id)).map(o=>o.id);data.orders.filter(o=>o.status==='ready').forEach(o=>seenReady.add(o.id));const staffChanged=JSON.stringify(snapshot?.staffNames)!==JSON.stringify(data.staffNames),configChanged=JSON.stringify(snapshot?.boardText)!==JSON.stringify(data.boardText),next=JSON.stringify([data.orders,data.warningMinutes]);snapshot=data;connection(true);
 const water=$('on-water'),count=data.onWaterCount;water.hidden=!Number.isSafeInteger(count)||count<=0;water.textContent=water.hidden?'':'На воде — '+count;document.body.classList.toggle('has-water',!water.hidden);bindBoardText(boardText());if(staffChanged||configChanged)layoutStaff();
 if(arrivals.length&&!reconnecting){arrivals.forEach(id=>highlightUntil.set(id,Date.now()+4000));chime();}if(next!==signature||configChanged){signature=next;rebuild(arrivals);} }
let audioContext=null,soundWanted=true;
try{soundWanted=localStorage.getItem('cafe-board-sound')!=='off';}catch{}
function setupAudio(){try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;if(!audioContext){audioContext=new Audio();}if(soundWanted){const resumed=audioContext.resume();if(resumed?.catch)resumed.catch(()=>{});}}catch{}}
function chime(){if(!soundWanted||audioContext?.state!=='running')return;try{const start=audioContext.currentTime;core.readyMelody.forEach(note=>{const oscillator=audioContext.createOscillator(),gain=audioContext.createGain(),at=start+note.at,end=at+note.duration;oscillator.type='sine';oscillator.frequency.value=note.frequency;gain.gain.setValueAtTime(0,at);gain.gain.linearRampToValueAtTime(.11,at+.025);gain.gain.exponentialRampToValueAtTime(.001,end-.02);gain.gain.linearRampToValueAtTime(0,end);oscillator.connect(gain);gain.connect(audioContext.destination);oscillator.start(at);oscillator.stop(end);oscillator.onended=()=>{oscillator.disconnect();gain.disconnect();};});}catch{}}

document.addEventListener('pointerdown',()=>{if(soundWanted)setupAudio();});
if(soundWanted)setupAudio();

let pollTimer;async function poll(){if(demo)return;clearTimeout(pollTimer);const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),8000);try{const r=await fetch('/api/cafe/board',{cache:'no-store',credentials:'omit',signal:controller.signal});if(!r.ok)throw Error('Нет связи');accept(await r.json());}catch{connection(false);}finally{clearTimeout(timeout);pollTimer=setTimeout(poll,5000);}}
function tick(){const now=new Date(Date.now()+offset);$('time').textContent=now.toLocaleTimeString('ru-RU',{timeZone:'Europe/Moscow',hour:'2-digit',minute:'2-digit'});$('date').textContent=now.toLocaleDateString('ru-RU',{timeZone:'Europe/Moscow',day:'2-digit',month:'long'});$('weekday').textContent=now.toLocaleDateString('ru-RU',{timeZone:'Europe/Moscow',weekday:'short'});for(const col of columns)if(col.pages.length>1&&Date.now()-col.at>=col.seconds*1000){col.page=(col.page+1)%col.pages.length;col.at=Date.now();render(col);}if(staffGroups.length>1&&Date.now()-staffAt>=12000){staffPage=(staffPage+1)%staffGroups.length;staffAt=Date.now();$('staff-names').textContent=core.staffText(staffGroups[staffPage]);}timers();if(!demo&&lastGood&&Date.now()+offset-lastGood>15000)connection(false);}
window.addEventListener('resize',()=>{if(!layoutPending){layoutPending=true;requestAnimationFrame(()=>{rebuild();layoutStaff();});}});document.addEventListener('visibilitychange',()=>{if(!document.hidden)tick();});setInterval(tick,1000);tick();if(demo)accept(window.CafeBoardDemo(query.get('scenario')||'normal'));else poll();
})();
